// Stand-in for the app's database.
export type Workspace = {
  id: string;
  name: string;
  email: string;
  plan: "free" | "pro";
  // Lago customer external_id is the workspace id; the subscription has its own durable id.
  lagoSubscriptionId?: string;
};
export type Generation = { id: string; workspaceId: string; model: string; inputTokens: number; outputTokens: number; createdAt: Date };
// Outbox row written alongside each generation; a worker delivers it to Lago.
export type UsageOutboxRow = {
  id: string; // = generation id, used as Lago transaction_id
  subscriptionId: string;
  metricCode: string;
  occurredAt: Date;
  properties: Record<string, string | number>;
  status: "pending" | "delivered" | "conflict" | "failed";
  attempts: number;
  lastError?: string;
};
export type WebhookInboxRow = { uniqueKey: string; payload: unknown; receivedAt: Date; processedAt?: Date };
export const db = {
  workspaces: new Map<string, Workspace>(),
  generations: new Map<string, Generation>(),
  usageOutbox: new Map<string, UsageOutboxRow>(),
  webhookInbox: new Map<string, WebhookInboxRow>(),
};

// App-side billing flow: provisioning, durable usage delivery, access checks, webhooks.
import { db, type Generation, type Workspace } from "@/lib/db";
import { configFromEnv, createSubscription, eventPayload, LagoError, sendUsage, storedEvent, upsertCustomer } from "./lago";

export const PLAN_CODE = "pro";
export const TOKENS_METRIC = "llm_tokens";
const CURRENCY = "USD";
const MAX_DELIVERY_ATTEMPTS = 10;

// Call when a workspace signs up for (or upgrades to) the paid plan.
// Activate the subscription before sending usage: earlier events are not billed.
export async function provisionBilling(workspace: Workspace) {
  const config = configFromEnv();
  await upsertCustomer(config, { id: workspace.id, name: workspace.name, email: workspace.email, currency: CURRENCY });
  const subscriptionId = workspace.lagoSubscriptionId ?? `sub_${workspace.id}`;
  workspace.lagoSubscriptionId = subscriptionId; // persist before the call so retries reuse the id
  try {
    await createSubscription(config, { id: subscriptionId, customerId: workspace.id, planCode: PLAN_CODE });
  } catch (error) {
    // Retrying with the same external_id after a lost response is fine; anything else is real.
    if (!(error instanceof LagoError && error.status === 422 && JSON.stringify(error.body).includes("value_already_exist"))) throw error;
  }
  workspace.plan = "pro";
}

// Write the usage record in the same transaction as the generation. Never call Lago inline.
export function recordUsage(generation: Generation) {
  const workspace = db.workspaces.get(generation.workspaceId);
  if (!workspace?.lagoSubscriptionId) return;
  db.usageOutbox.set(generation.id, {
    id: generation.id,
    subscriptionId: workspace.lagoSubscriptionId,
    metricCode: TOKENS_METRIC,
    occurredAt: generation.createdAt,
    properties: { tokens: generation.inputTokens + generation.outputTokens, model: generation.model },
    status: "pending",
    attempts: 0,
  });
}

// Worker: deliver pending outbox rows. Safe to run repeatedly and concurrently with replays,
// because transaction_id and timestamp come from the stored row.
export async function deliverPendingUsage() {
  const config = configFromEnv();
  for (const row of db.usageOutbox.values()) {
    if (row.status !== "pending") continue;
    row.attempts++;
    try {
      const result = await sendUsage(config, row);
      if (result === "accepted") {
        row.status = "delivered";
      } else {
        // Duplicate: only treat as delivered if Lago's stored event matches ours.
        const stored = await storedEvent(config, row.id);
        const ours = eventPayload(row);
        const same = stored.external_subscription_id === ours.external_subscription_id && stored.code === ours.code &&
          String(stored.properties.tokens) === String(ours.properties.tokens);
        row.status = same ? "delivered" : "conflict";
        if (!same) row.lastError = "transaction_id already used by a different event";
      }
    } catch (error) {
      row.lastError = error instanceof LagoError ? `${error.status} ${JSON.stringify(error.body)}` : String(error);
      // Non-transient 4xx are contract errors: stop retrying and surface them.
      const contractError = error instanceof LagoError && error.status < 500 && error.status !== 429;
      if (contractError || row.attempts >= MAX_DELIVERY_ATTEMPTS) row.status = "failed";
    }
  }
}

// Fire-and-forget delivery kick for this in-process stand-in; use a real queue/cron in production.
export function scheduleUsageDelivery() {
  deliverPendingUsage().catch((error) => console.error("usage delivery failed", error));
}

// Access check before the expensive LLM call.
export function canGenerate(workspace: Workspace | undefined): boolean {
  if (!workspace) return false;
  return workspace.plan === "free" || Boolean(workspace.lagoSubscriptionId);
}

// Webhook processing runs after the event is durably stored in the inbox.
export async function processWebhook(uniqueKey: string) {
  const row = db.webhookInbox.get(uniqueKey);
  if (!row || row.processedAt) return;
  const payload = row.payload as { webhook_type: string; [key: string]: any };
  switch (payload.webhook_type) {
    case "invoice.created":
      // e.g. email the invoice / store payload.invoice for the billing page
      break;
    case "wallet.depleted_ongoing_balance":
      // e.g. notify the customer to top up; canGenerate can start blocking here
      break;
    case "subscription.terminated": {
      const subscriptionId = payload.subscription?.external_id;
      for (const workspace of db.workspaces.values()) {
        if (workspace.lagoSubscriptionId === subscriptionId) {
          workspace.lagoSubscriptionId = undefined;
          workspace.plan = "free";
        }
      }
      break;
    }
  }
  row.processedAt = new Date();
}

import { db } from "@/lib/db";
import { summarize } from "@/lib/llm";
import { canGenerate, recordUsage, scheduleUsageDelivery } from "@/lib/billing";

export async function POST(request: Request) {
  const { workspaceId, text } = await request.json();
  if (!canGenerate(db.workspaces.get(workspaceId))) {
    return Response.json({ error: "billing not active for this workspace" }, { status: 402 });
  }
  const result = await summarize(text);
  const generation = {
    id: crypto.randomUUID(),
    workspaceId,
    model: result.model,
    inputTokens: result.usage.input_tokens,
    outputTokens: result.usage.output_tokens,
    createdAt: new Date(),
  };
  db.generations.set(generation.id, generation);
  recordUsage(generation);
  scheduleUsageDelivery();
  return Response.json({ summary: result.summary });
}

import { db } from "@/lib/db";
import { processWebhook } from "@/lib/billing";
import { configFromEnv, verifyWebhook, webhookPublicKey } from "@/lib/billing/lago";

let publicKeyPem: string | undefined;

export async function POST(request: Request): Promise<Response> {
  const config = configFromEnv();
  if (!process.env.LAGO_WEBHOOK_HMAC_KEY) publicKeyPem ??= await webhookPublicKey(config);
  const rawBody = await request.text();
  let payload: unknown;
  try {
    // The JWT issuer is the Lago instance's API URL.
    payload = verifyWebhook(rawBody, request.headers, { issuer: config.apiUrl, publicKeyPem, hmacKey: process.env.LAGO_WEBHOOK_HMAC_KEY });
  } catch {
    return new Response("invalid signature", { status: 401 });
  }
  const uniqueKey = request.headers.get("x-lago-unique-key");
  if (!uniqueKey) return new Response("missing unique key", { status: 400 });
  if (!db.webhookInbox.has(uniqueKey)) {
    db.webhookInbox.set(uniqueKey, { uniqueKey, payload, receivedAt: new Date() });
    processWebhook(uniqueKey).catch((error) => console.error("webhook processing failed", error)); // async
  }
  return new Response(null, { status: 204 }); // only after durable storage
}

