test("HMAC webhook: valid accepted, tampered rejected", () => {
  const body = JSON.stringify({ webhook_type: "invoice.created", invoice: { total_amount_cents: 5140 } });
  const signature = createHmac("sha256", "secret").update(body).digest("base64");
  const headers = new Headers({ "x-lago-signature": signature, "x-lago-signature-algorithm": "hmac" });
  assert.equal(verifyWebhook(body, headers, { issuer: "x", hmacKey: "secret" }).webhook_type, "invoice.created");
  assert.throws(() => verifyWebhook(body.replace("5140", "1"), headers, { issuer: "x", hmacKey: "secret" }));
});

test("JWT webhook: valid accepted, tampered body and wrong issuer rejected", () => {
  const { privateKey, publicKey } = generateKeyPairSync("rsa", { modulusLength: 2048 });
  const publicKeyPem = publicKey.export({ type: "spki", format: "pem" }).toString();
  const body = JSON.stringify({ webhook_type: "subscription.terminated" });
  const b64 = (o: unknown) => Buffer.from(JSON.stringify(o)).toString("base64url");
  const signingInput = `${b64({ alg: "RS256" })}.${b64({ iss: "https://lago.test", data: body })}`;
  const jwt = `${signingInput}.${sign("RSA-SHA256", Buffer.from(signingInput), privateKey).toString("base64url")}`;
  const headers = new Headers({ "x-lago-signature": jwt, "x-lago-signature-algorithm": "jwt" });
  assert.ok(verifyWebhook(body, headers, { issuer: "https://lago.test", publicKeyPem }));
  assert.throws(() => verifyWebhook(body + " ", headers, { issuer: "https://lago.test", publicKeyPem }));
  assert.throws(() => verifyWebhook(body, headers, { issuer: "https://evil.test", publicKeyPem }));
});

